// مولّد دراسة الجدوى الاقتصادية — مُرضي
// الأرقام تُحسب في feasibilityCompute (كود)، والنموذج يكتب التحليل والسوق فقط
import { computeFeasibility, renderProjectionTable, renderCashflowTable, renderFeasibilitySummary, computeCredit, renderCreditTable, renderMonthlyTable, renderScenarioTable, computeBreakPoints, renderBreakPointsTable, renderCombinedTable, type FeasibilityInputs, type FeasibilityResult, type CreditPack } from './feasibilityCompute';
import { orderForClient, familyOf, pledgeWarning, FAMILY_LABEL } from './productPreference';

// صف جهة تمويل مرشحة — يُقرأ من match_results ولا يُولَّد بنموذج
export interface FunderRow {
  provider: string; product?: string; region?: string; requirements?: string;
  amount_range?: string; timeline?: string; apply_channel?: string; apply_url?: string; required_docs?: string;
  gaps?: string[] | null; fit_score?: number; verdict?: string;
}

const ANTHROPIC_URL = 'https://api.anthropic.com/v1/messages';
const MODEL = 'claude-sonnet-4-6';

export interface FeasibilityContext {
  companyName: string;
  crNumber?: string;
  city?: string;
  projectDescription: string;      // وصف المشروع
  sectorText: string;              // القطاع بنص حر
  audience: 'financier' | 'investor' | 'regulator' | 'internal';
  projectKind: 'new' | 'expansion';
  location?: string;
  capacityNote?: string;           // الطاقة المستهدفة
  staffNote?: string;              // العمالة
  existingRevenue?: number;        // للتوسعة فقط
  quick?: boolean;                 // الفحص الائتماني السريع: أرقام محسوبة فقط، بلا بحث سوق ولا سرد ولا جهات
  inputs: FeasibilityInputs;
}

export interface FeasibilitySections {
  // لجنة الائتمان تقرأ الصفحة الأولى ثم تقرّر هل تقرأ الباقي. فأربعةُ أرقام
  // في صدر الوثيقة تُغني عن أربعين صفحة، وغيابُها يجعل القارئ يبحث عن حكمه
  // في جداولٍ لم تُكتب له.
  topNumbers: string;
  executiveSummary: string;
  marketStudy: string;
  competition: string;
  // ═══ أقسام الجدوى الاقتصادية ═══
  // كانت الوثيقة تقيس السداد وتصف السوق، فتُقرأ ائتمانيةً بحتة. ودراسةُ
  // الجدوى لا تكتمل بغير أربعةٍ زيادةً على ذلك: **تحليل الموقع التنافسي**
  // الذي يقول أين يقف المشروع من منافسيه، و**الخطة التشغيلية والتسويقية**
  // التي تقول كيف يُدار ويُباع، و**الامتثال النظامي** الذي يقول ما الذي
  // يمنع تشغيله أصلاً، و**الأثر الاقتصادي** الذي يقرؤه المستثمر والجهة
  // الحكومية معاً. وبغيابها تُجيب الدراسة عن «هل يسدّد؟» وتسكت عن «هل
  // يستحق؟» — وهو السؤال الذي يدفع العميل ثمن الدراسة لأجله.
  swot: string;
  operationalPlan: string;
  legalCompliance: string;
  economicImpact: string;
  technicalStudy: string;
  // ═══ ما تعلّمناه من ملفٍ حيّ — سبتمبر ٢٠٢٦ ═══
  // سأل صاحبُ مشروعٍ عقاري سؤالاً أسقط الدراسة كلها: «طلبتُ المبلغ فاشتريتُ
  // به الأرض — فبماذا أبني؟». والدراسة كانت تذكر المبلغ ولا تشرح **كيف
  // يدور**: أنه حدٌّ يُسحب ويُطفأ من المتحصّلات ثم يُعاد سحبه، وأن تكلفة
  // المشروع قد تبلغ ضِعفه. فصار لكل دراسة قسمٌ يجيب هذا السؤال قبل أن
  // يُطرح — لأن لجنة الائتمان تطرحه أيضاً، وسكوتُ الوثيقة عنه يردّ الملف.
  facilitySizing: string;
  // ★ «نقاط الضعف» أُسقطت من الوثيقة — لا إخفاءً بل لأنها كانت تُسلّم لجنةَ
  //   الائتمان أسبابَ الرفض مكتوبةً بقلمنا. والصدق لا يُشترط أن يكون
  //   انتحاراً: كلُّ ما كان يُكتب ضعفاً يُكتب هنا **بنداً يحتاج معالجة
  //   ومعالجته القائمة بجانبه**. فلا يُخفى شيء، ولا يُهدى شيء.
  remediation: string;
  // وما ينقص الملف من مستندات لا يُعرض جدولَ «غير متوفّر» — بل مساراً
  // مرتّباً بمراحله، فالنقص الذي له موعدٌ ليس نقصاً بل خطوةٌ لم تحن.
  completionPath: string;
  // وفي الملف نفسه كتبنا أن العميل «يقدّم ضماناً شخصياً وسنداً لأمر» ولم
  // يقل ذلك قط. وإلزامُ العميل أمام الممول بما لم يلتزم به خطأٌ لا يُغتفر:
  // يُفاوَض على أساسه ثم يتراجع فيسقط الملف كلّه. فالقسم يصف ما **تُتيحه
  // بنية المشروع** من ضمان، ويترك الحزمة النهائية لخطاب الشروط.
  securityStructure: string;
  // ═══ ما تعلّمناه من المراجعة الثانية للملف العقاري — سبتمبر ٢٠٢٦ ═══
  // ثلاثةُ دروسٍ خرجت من ملفٍ واحدٍ راجعه صاحبُ المشروع بنفسه:
  // (١) كانت الدراسة تكتب في خانة المصدر «إفادة الطالب» أمام سعر البيع
  //     وتكلفة المتر ومدّة التنفيذ. ولجنةُ الائتمان تخصم من مصداقية كلّ رقمٍ
  //     مصدرُه صاحبُ الطلب — فصار كلُّ مُدخلٍ سعريٍّ يُسنَد إلى متوسط السوق
  //     ويُقارن به في جدولٍ صريح، ومعه **المقاس المناسب لمثل هذا المشروع**
  //     (مساحةً أو طاقةً أو عدد وحدات) ولماذا هو نطاقُه.
  marketBenchmark: string;
  // (٢) «الشريحة المستهدفة» كانت فقرةً واحدة، فبدت مخاطرةُ التصريف معلّقةً
  //     على شريحةٍ واحدة. وحين فُصّلت إلى ثلاثِ شرائح — لكلٍّ منتجُها ومحرّكُ
  //     شرائها — صار التنويع نفسه حجّةً ائتمانية: ضعفُ واحدةٍ لا يوقف البيع.
  targetSegments: string;
  // (٣) ولم يكن في الوثيقة إلا مسارُ تصريفٍ واحد. والمشروع الذي له مساران
  //     — بيعٌ مبكّر أو بيعٌ بعد الاكتمال، توزيعٌ مباشر أو عبر وكيل — يُقاس
  //     عليهما معاً بالأرقام، ويُختم بتوصية. ومعهما شكلُ السداد: السماحُ
  //     يُربط بمدّة التأسيس لا يُختار اعتباطاً، ثم تُجدوَل الأقساط.
  exitRoutes: string;
  assumptionsNote: string;
  risks: string;
  conclusion: string;
  funderQA: string;
  sources: string[];
}

const AUD: Record<FeasibilityContext['audience'], string> = {
  financier: 'جهة تمويل — ركّز على القدرة على السداد وتغطية الأقساط والضمانات وحساسية التدفق النقدي',
  investor: 'مستثمر — ركّز على حجم السوق والنمو والعائد وفرصة التوسع وميزة المشروع التنافسية',
  regulator: 'جهة حكومية أو ترخيص — ركّز على الامتثال والاشتراطات والأثر الاقتصادي والتوطين',
  internal: 'استخدام داخلي لصاحب المشروع — ركّز على الواقعية وما يجب التحقق منه قبل الالتزام',
};

export async function generateFeasibility(ctx: FeasibilityContext): Promise<{ sections: FeasibilitySections; result: FeasibilityResult; credit: CreditPack; error?: string }> {
  const result = computeFeasibility(ctx.inputs);
  const credit = computeCredit(ctx.inputs, result);
  const bp = computeBreakPoints(ctx.inputs, result, credit);
  const n = (v: number) => Math.round(v).toLocaleString('en-US');

  // الفحص السريع لا يستدعي النموذج إطلاقاً — الأرقام كلها كود، فيخرج في ثوانٍ وبكلفة صفر
  if (ctx.quick) return { sections: empty(), result, credit };

  // حجم المشروع يحدد نطاقه التنافسي — منشأة بمليون ريال منافسها الحي لا السلاسل الوطنية
  const inv = result.totalInvestment;
  const scaleLabel = inv <= 3_000_000 ? 'مشروع صغير — منفذ أو فرع واحد'
    : inv <= 20_000_000 ? 'مشروع متوسط — عدة فروع أو خط إنتاج' : 'مشروع كبير — حضور على مستوى المنطقة أو المملكة';
  const scaleRadius = inv <= 3_000_000 ? 'الحي أو النطاق الجغرافي المباشر داخل المدينة، مع قنوات التوصيل الرقمية التي تصل إلى هذا النطاق'
    : inv <= 20_000_000 ? 'المدينة أو المنطقة' : 'السوق الوطني';

  const mkPrompt = (marketBlock: string, jsonSpec: string) => 'أنت خبير دراسات جدوى في السوق السعودي. اكتب أقسام دراسة جدوى لمشروع محدد أدناه.\n\n'
    + 'بيانات المشروع كما قدّمها العميل:\n'
    + '- المنشأة: ' + ctx.companyName + (ctx.crNumber ? ' (سجل ' + ctx.crNumber + ')' : '') + '\n'
    + '- المدينة: ' + (ctx.city || 'غير محدد') + (ctx.location ? ' | موقع المشروع: ' + ctx.location : '') + '\n'
    + '- القطاع: ' + ctx.sectorText + '\n'
    + '- وصف المشروع: ' + ctx.projectDescription + '\n'
    + '- نوعه: ' + (ctx.projectKind === 'new' ? 'مشروع جديد من الصفر' : 'توسعة نشاط قائم') + (ctx.existingRevenue ? ' — إيراد النشاط القائم ' + n(ctx.existingRevenue) + ' ريال' : '') + '\n'
    + (ctx.capacityNote ? '- الطاقة المستهدفة: ' + ctx.capacityNote + '\n' : '')
    + (ctx.staffNote ? '- العمالة: ' + ctx.staffNote + '\n' : '')
    + '- التكلفة الرأسمالية: ' + n(ctx.inputs.capex) + ' ريال | رأس المال العامل: ' + n(ctx.inputs.workingCapital) + ' ريال\n'
    + '- افتراضات التشغيل كما قدّمها العميل: سعر الوحدة ' + n(ctx.inputs.unitPrice) + ' ريال | وحدات السنة الأولى ' + n(ctx.inputs.unitsYear1)
      + ' | نمو المبيعات ' + ctx.inputs.growthRate + '% سنوياً | التكلفة المتغيرة ' + ctx.inputs.variableCostPct + '% من الإيراد | المصاريف الثابتة '
      + n(ctx.inputs.fixedCostsAnnual) + ' ريال سنوياً تنمو ' + ctx.inputs.inflationRate + '% سنوياً\n'
    + '- التمويل المطلوب: ' + n(ctx.inputs.financingAmount) + ' ريال على ' + ctx.inputs.financingYears + ' سنوات بكلفة سنوية ' + ctx.inputs.financingRate + '% | مساهمة المؤسس: ' + n(ctx.inputs.ownFunds) + ' ريال\n\n'
    + 'الأرقام المحسوبة (محسوبة برمجياً — لا تعد حسابها ولا تخالفها):\n'
    + '- إجمالي الاستثمار ' + n(result.totalInvestment) + ' ريال | فجوة التمويل ' + n(result.fundingGap) + ' ريال\n'
    + '- حجم المشروع: ' + scaleLabel + ' | نطاقه التنافسي: ' + scaleRadius + '\n'
    + '- هامش المساهمة ' + result.contributionMarginPct.toFixed(1) + '% | نقطة التعادل ' + n(result.breakEvenRevenue) + ' ريال سنوياً\n'
    + '- فترة الاسترداد: ' + (result.paybackYears === null ? 'لا تُسترد خلال خمس سنوات بهذه الافتراضات' : result.paybackYears.toFixed(1) + ' سنة') + '\n'
    + '- القسط السنوي للتمويل ' + n(result.annualInstalment) + ' ريال (محسوب — لا تقل إنه غير محدد ولا تفترض غيره)\n'
    // مؤشرات التقييم تُمرَّر للنموذج ليبني عليها حكمه الاقتصادي بدل أن يصف
    // السيولة وحدها: الخلاصة تفصل «هل يستحق رأس المال» عن «هل يسدّد».
    + '- مؤشرات التقييم عند خصم ' + (result.discountRate * 100).toFixed(0) + '%: صافي القيمة الحالية ' + n(result.npv) + ' ريال'
      + ' | معدّل العائد الداخلي ' + (result.irr === null ? 'لا يُحتسب' : (result.irr * 100).toFixed(1) + '%')
      + ' | مؤشّر الربحية ' + (result.profitabilityIndex === null ? '—' : result.profitabilityIndex.toFixed(2))
      + ' | فترة الاسترداد المخصومة ' + (result.discountedPayback === null ? 'لا تُسترد خلال أفق الدراسة' : result.discountedPayback.toFixed(1) + ' سنة') + '\n'
    + '- صافي الربح المحاسبي (بعد الاستهلاك وكلفة التمويل): السنة الأولى ' + n(result.years[0].netProfit) + ' ريال، والسنة الخامسة ' + n(result.years[4].netProfit) + ' ريال\n'
    + '- صافي التدفق النقدي بعد القسط الكامل: السنة الأولى ' + n(result.years[0].cashFlow) + ' ريال، والسنة الخامسة ' + n(result.years[4].cashFlow) + ' ريال\n'
    + '- الاستهلاك السنوي ' + n(result.years[0].depreciation) + ' ريال، وكلفة التمويل السنوية ' + n(result.years[0].financeCharge) + ' ريال من أصل قسط ' + n(result.years[0].debtService) + ' ريال (الباقي سداد أصل)\n\n'
    + '\nمؤشرات الائتمان (محسوبة برمجياً — استند إليها ولا تعِد حسابها):\n'
    + '- نسبة تغطية خدمة الدين: أدناها ' + (credit.minDscr === null ? 'لا تنطبق' : credit.minDscr.toFixed(2) + '× ومتوسطها ' + (credit.avgDscr as number).toFixed(2) + '×') + ' — ' + credit.verdict + '\n'
    + '- التدفق المتاح لخدمة الدين في السنة الأولى ' + n(credit.years[0].cfads) + ' ريال = صافي الربح + الاستهلاك ' + n(credit.years[0].depreciation) + ' + كلفة التمويل ' + n(credit.years[0].financeCharge) + '\n'
    + '- التدفق الشهري للسنة الأولى يبلغ أعمق نقطة نقدية في الشهر ' + (credit.deepestMonth ? credit.deepestMonth.month : 0) + '، فرأس المال العامل الفعلي اللازم ' + n(credit.workingCapitalNeeded) + ' ريال\n'
    + '- السيناريو المتحفظ (مبيعات -20% وتكاليف +10%): تغطية ' + (credit.scenarios[0].dscrY1 === null ? '—' : credit.scenarios[0].dscrY1.toFixed(2) + '×') + ' — ' + credit.scenarios[0].verdict + '\n'
    + (credit.combined ? '- التغطية المجمّعة للمنشأة بعد التوسعة (النشاط القائم + المشروع مقابل خدمة الدين كلها): أدناها '
      + (credit.combined.minDscr === null ? '—' : credit.combined.minDscr.toFixed(2) + '× ومتوسطها ' + (credit.combined.avgDscr as number).toFixed(2) + '×')
      + ' — ' + credit.combined.verdict + '. وهذا هو الرقم الذي تقرؤه جهة التمويل، لأنها تقرض المنشأة لا الفرع.\n' : '')
    + '- زكاة تقديرية 2.5% مخصومة في الأرقام أعلاه: ' + n(result.years[0].zakat) + ' ريال في السنة الأولى (الوعاء الفعلي وفق قواعد هيئة الزكاة والضريبة والجمارك)\n'
    + '- حدود الأمان: الإيراد اللازم لتغطية 1.25× هو ' + n(bp.requiredRevenue) + ' ريال، أي '
      + (bp.headroomPct === null ? '—' : bp.headroomPct >= 0
        ? 'أن المشروع يحتمل تراجعاً في المبيعات حتى ' + bp.headroomPct.toFixed(1) + '% قبل النزول عن الحد'
        : 'أن المبيعات تحتاج زيادة ' + Math.abs(bp.headroomPct).toFixed(1) + '% لبلوغ الحد')
      + ' | المطلوب ' + Math.ceil(bp.requiredUnitsDay) + ' وحدة/يوم مقابل ' + Math.round(bp.plannedUnitsDay) + ' مخططة'
      + ' | أقصى مصاريف ثابتة ' + n(bp.maxFixedCosts) + ' ريال | أدنى سعر وحدة ' + n(bp.minUnitPrice) + ' ريال'
      + ' | التشغيل يتحول إلى تدفق موجب في ' + (bp.operatingBreakEvenMonth === null ? 'ما بعد السنة الأولى' : 'الشهر ' + bp.operatingBreakEvenMonth) + '\n\n'
    + marketBlock
    + 'الجمهور المستهدف للدراسة: ' + AUD[ctx.audience] + '\n\n'
    + 'قواعد إلزامية:\n'
    + '(ج١) أرقام السوق: اذكر أرقاماً كمّية فعلية لحجم السوق ونموه ومتوسط الإنفاق ومؤشرات القطاع — لا تترك القسم بلا أرقام. ما ورد في «نتائج بحث السوق» أعلاه انسبه إلى مصدره باسمه وسنته، وما لم يرد فيه اكتبه بصياغة «تقدير استرشادي مبني على مؤشرات القطاع المعلنة». ولا تنسب رقماً إلى جهة بعينها ما لم يرد في نتائج البحث أعلاه. ولا تعتمد رقماً منسوباً إلى صحيفة تنقل عن «تقرير سوق» غير مُسمّى — إمّا أن يُنسب إلى التقرير نفسه باسمه، أو يُكتب تقديراً استرشادياً؛ فأضعف مصدر في الوثيقة يُسقط ما حوله إذا شكّك فيه الممول. وإن تعارض مصدران في حجم السوق فاذكر التقديرين معاً بمصدريهما وبيّن أيهما اعتمدت ولماذا، ولا تضعهما متجاورين بلا تعليق.\n'
    + '(ج١ب) في الخلاصة والمخاطر: علّق صراحةً على نسبة تغطية خدمة الدين وعلى السيناريو المتحفظ، وبيّن ما إذا كان الهيكل المطلوب يتحمّل، وإن كانت التغطية دون 1.25× فاقترح معالجة محددة (تمديد الأجل أو رفع المساهمة أو خفض المطلوب).\n'
    + '(ج٢) لا تعد بعائد ولا تكتب أي عبارة ضمان للنجاح أو للربح، ولا تصف المشروع بأنه مضمون أو مؤكد.\n'
    + '(ج٣) لا تخالف الأرقام المحسوبة أعلاه ولا تعيد حسابها. وإن كانت النتيجة ضعيفة (تعادل مرتفع أو استرداد بعيد) فاذكر ذلك بوضوح ولا تجمّله.\n'
    + '(ج٤) لا تنسب للمنشأة أي صفة لم ترد أعلاه — لا خبرة ولا عملاء ولا تراخيص ولا أصول.\n'
    + '(ج٤ب) لا تكرر عنوان القسم في أول سطر من نصه. وإن احتجت جدولاً فاكتبه بصيغة الأنبوب | فقط، ولا تستخدم ** ولا # ولا أي ترميز آخر.\n'
    + '(ج٦) نطاق المنافسة يُحدَّد بحجم المشروع المذكور أعلاه. اكتب قسم المنافسين عن المنافسين الفعليين في ذلك النطاق وعند ذلك الحجم: عددهم وأنماطهم ومستوى أسعارهم وقنواتهم. أما السلاسل الكبرى والعلامات الوطنية فتُذكر — إن لزم — في سياق بنية السوق وسقف الأسعار وتوقعات العميل فقط، ولا تُقدَّم بوصفها منافساً مباشراً لمشروع بهذا الحجم: مقارنة منشأة صغيرة بسلاسل وطنية تُضعف الملف أمام الممول ولا تعطي العميل معلومة قابلة للتنفيذ. وإن لم تتوفر أسماء على مستوى النطاق فاوصف بنية المنافسة فيه بدل حشو القسم بأسماء لا تخصه.\n'
    + '(ج٧) المخاطر تخص هذا المشروع وحده: كل خطر يُشتق من أرقامه أو موقعه أو تراخيصه أو هيكل تمويله، ويقترن بإجراء تخفيفي ينفّذه المشروع فعلاً. ويُمنع منعاً باتاً إدراج معدلات تعثّر أو إغلاق أو خروج عامة للقطاع (نسبة المنشآت التي أُغلقت خلال مدة ونحوها) — فهي حكم على القطاع لا على المشروع، ولا يملك المشروع إجراءً يخفّضها، فتضر الدراسة دون أن تضيف معلومة. وهذا لا يُخلّ بالقاعدة (ج١ب): نسبة التغطية المحسوبة والسيناريو المتحفظ يبقيان إلزاميين لأنهما مشتقان من أرقام العميل نفسه ولهما معالجات محددة.\n'
    + '(ج٨) ⚠️ لا تُلزم العميل أمام جهة التمويل بشيء لم يذكره في بياناته: لا ضماناً شخصياً ولا كفالةً ولا سنداً لأمر ولا رهن أصلٍ لم يُذكر ولا تعهّداً بضخّ مال. ووصفُ ما تُتيحه بنية المشروع من ضمان شيء، ونسبةُ تعهّدٍ إلى العميل شيء آخر — والثاني ممنوع منعاً باتاً، لأن الممول يفاوض على أساسه فإذا تراجع العميل سقط الملف كلّه. وحزمة الضمانات النهائية تُترك لسياسة المموّل ولخطاب الشروط.\n'
    + '(ج٩) إن كان الإنفاق الرأسمالي على مراحل أو كانت المتحصّلات ترد قبل اكتمال المشروع، فاعرض المطلوب بوصفه حدّاً ائتمانياً يُسحب على دفعات ويُطفأ من المتحصّلات ويُعاد سحبه — لا مبلغاً مقطوعاً. والفرق بين «حدّ» و«مبلغ» هو الفرق بين ملفٍ يُدرَس وملفٍ يُرَدّ، ولأن الحدّ الدوّار يكفي مشروعاً تكلفته أضعافه.\n'
    + '(ج١٠) لا تكتب في الوثيقة كلها قسماً ولا خانةً ولا عنواناً باسم «نقاط الضعف». والصدق باقٍ كما هو: كلُّ ما كان يُكتب ضعفاً يُكتب في جدول المعالجات مقروناً بمعالجته القائمة. فالوثيقة تذهب إلى لجنة ائتمان، وقائمةُ ضعفٍ عاريةٍ فيها أسبابُ رفضٍ كتبناها نحن عن عميلنا — والصدق لا يُشترط أن يكون انتحاراً.\n'
    + '(ج١١) في تعليقك على السيناريو المتحفظ افصل ما يُقلق المالك عمّا يُقلق المموّل: الهامش قد يذوب والتغطية تبقى، لأن التغطية تُقاس بالتدفق لا بالربح. فإن بقيت التغطية مقبولةً في السيناريو المتحفظ فقل ذلك صريحاً — فهذه هي الجملة التي تُمرّر الملف.\n'
    + '(ج١٢) ⚠️ مصدرُ المُدخل يُقرأ قبل قيمته. لا تكتب «إفادة الطالب» مصدراً وحيداً لسعر بيعٍ ولا لتكلفة وحدةٍ ولا لمدّة تنفيذٍ ولا لسعر أصلٍ متى وُجد لذلك متوسطٌ سوقي — فلجنة الائتمان تخصم من مصداقية كل رقمٍ مصدرُه صاحبُ الطلب. اكتب متوسط السوق وانسبه إليه، ثم قل صراحةً هل طابقته إفادةُ العميل أم خالفتها وبكم، وأيّهما اعتمدتَ ولماذا. وإن لم يوجد للمُدخل مرجعٌ سوقي فاكتبه «افتراض المكتب» لا «إفادة الطالب».\n'
    + '(ج١٣) المقاسُ المناسب جزءٌ من الجدوى لا تفصيلٌ فني: قل ما هو النطاق المعتاد لمشروعٍ بهذا النوع (مساحةً أو طاقةً أو عدد وحداتٍ أو عدد منافذ)، وأين يقع هذا المشروع منه، ولماذا يضرّه النزول تحته والصعود فوقه. فالمقاس الواقع في وسط نطاقه حجّةٌ ائتمانية، والواقع خارجه سؤالٌ يجب أن تسبقه بالجواب.\n'
    + '(ج١٤) الشرائح المستهدفة لا تُكتب فقرةً واحدة: اذكر ثلاث شرائح على الأقل، لكلٍّ منها المنتج أو الخدمة التي تخدمها ومحرّكُ شرائها، ثم اختم بسطرٍ يقول إن مخاطرة التصريف موزّعةٌ على محرّكاتٍ مستقلّة لا معلّقةٌ على شريحةٍ واحدة. وإن كان للمشروع شريحةٌ واحدة فقل ذلك صراحةً واذكره في جدول المعالجات.\n'
    + '(ج١٥) إن كان للمشروع أكثر من مسارٍ للتصريف أو البيع أو التشغيل — بيعٌ مبكّر أو بعد الاكتمال، بيعٌ مباشر أو عبر وكيل، تشغيلٌ ذاتي أو تأجير — فاعرض المسارين معاً بالأرقام المحسوبة لا مساراً واحداً، ثم أوصِ بأحدهما وبيّن بكم يفوق الآخر. فالوثيقة التي تعرض مساراً واحداً تُقرأ افتراضاً، والتي تعرض مسارين تُقرأ قراراً.\n'
    + '(ج١٦) شكلُ السداد يُشتقّ من المشروع لا يُختار: إن كان للمشروع مدّةُ تأسيسٍ أو تنفيذٍ قبل أول إيراد، فاربط فترة السماح بها صراحةً (سماحٌ يساوي مدّة التأسيس) ثم قل على كم تُجدوَل الأقساط بعدها، وهل يجوز الإطفاء المبكّر من المتحصّلات. ولا تذكر مدّة سماحٍ بلا تبريرٍ من الجدول الزمني نفسه.\n'
    + '(ج١٧) إن ضاقت نسبةٌ ائتمانية — تغطيةٌ دون الحدّ، أو دينٌ إلى تكلفةٍ فوق المعتاد، أو غيابُ مساهمةٍ نقدية — فقلها صريحةً ثم اعرض **ثلاث معالجاتٍ لا واحدة**: ضمانٌ عينيٌّ يُشترى بالتمويل ويُرهن، أو تأمينٌ ائتمانيٌّ على مبلغ التمويل عبر شركات التأمين المرخّصة، أو مساهمةٌ نقديةٌ من المالك بنسبةٍ محددة تُعيد النسبة إلى نطاقها. وصِفها بنداً تفاوضياً يُطرح على الطاولة لا عيباً في المشروع.\n'
    + '(ج١٨) إن كانت مساهمة المؤسس صفراً أو ضئيلةً جداً فلا تعرض عائداً مرفوعاً على حقوق الملكية — فهو بلا معنى بغير مساهمة. اعرض العائد على مستوى المشروع نفسه وقل صراحةً لماذا قِيس هكذا.\n'
    + '(ج٥) في حقل sources أدرج المصادر الواردة في نتائج البحث أعلاه فقط، ولا تخترع مصدراً ولا رابطاً.\n\n'
    + 'أرجع JSON فقط بلا أي نص آخر وبلا markdown:\n'
    + jsonSpec;

  // القسمان يُكتبان في نداءين متوازيين: نصف المخرجات لكل نداء فينتصف زمن الانتظار
  const SPEC_A = '{"topNumbers":"أربعة أرقام تُغني عن قراءة الوثيقة — كل رقم في سطر يبدأ بترقيم (١) (٢) (٣) (٤). اخترها من الأرقام المحسوبة أعلاه وحدها، وليكن فيها: حكمُ الجدوى الاقتصادية (صافي القيمة الحالية والعائد الداخلي)، ونقطةُ التعادل بما تعنيه عملياً، وحكمُ الجدوى الائتمانية (التغطية وما يقابلها من حدّ مقبول)، وهامشُ الأمان (كم يحتمل المشروع من تراجعٍ قبل أن ينكسر). كل سطر رقمٌ ثم جملةٌ واحدة تقول ماذا يعني — بلا مقدمات وبلا صفات","executiveSummary":"الملخص التنفيذي (فقرتان) مصاغ لجمهور الدراسة","marketStudy":"دراسة السوق: الحجم والنمو ومحرّكات الطلب ومستوى الأسعار، كل رقم بمصدره — والشرائح تُفصَّل في الحقل المستقل لا هنا","targetSegments":"الشرائح المستهدفة — جدول بثلاثة أعمدة: الشريحة | المنتج أو الخدمة التي تخدمها | ما يُحرّك شراءها. ثلاث شرائح على الأقل مشتقّة من طبيعة هذا المشروع ومدينته، لا شرائح عامة. ثم سطرٌ أخير يقرأ التنويع ائتمانياً: أن مخاطرة التصريف موزّعة على محرّكاتٍ مستقلّة لا معلّقة على شريحةٍ واحدة. وإن كان للمشروع شريحةٌ واحدة حقاً فقل ذلك صراحةً بدل اختراع شرائح","competition":"المنافسة عند حجم المشروع ونطاقه: بنية المنافسة في النطاق ومستوى الأسعار والقنوات، ثم موقع المشروع من تلك البنية وعوامل تمايزه فيها","swot":"الموقع التنافسي بصيغة جدول بعمودين وثلاثة صفوف فقط: نقاط القوة | الفرص | التهديدات السوقية. ثلاث إلى خمس نقاط في كل خانة، كلها خاصة بهذا المشروع في نطاقه لا عبارات عامة. ⚠️ ولا تكتب صفاً اسمه نقاط الضعف ولا تدرج ضعفاً في الخانات الثلاث — فما كان ضعفاً يُكتب في قسم المعالجات مقروناً بمعالجته، لا هنا عارياً","sources":["اسم المصدر — الرابط — السنة"]}';
  const SPEC_B = '{"technicalStudy":"الدراسة الفنية: الموقع والطاقة والمعدات والعمالة ومراحل التنفيذ","operationalPlan":"الجدوى التشغيلية وخطة التسويق: الهيكل الإداري ومن يدير المشروع يومياً، وسلسلة التوريد، وخطة جذب العملاء وقنواتها وتكلفة اكتساب العميل التقديرية، وكيف يُسعَّر المنتج مقارنةً بالسوق — بلا عموميات تسويقية","legalCompliance":"الجدوى القانونية والنظامية: التراخيص والاشتراطات اللازمة لهذا النشاط بعينه قبل التشغيل، والجهة المانحة لكل ترخيص، والالتزامات الزكوية والضريبية (القيمة المضافة والزكاة وأي ضريبة قطاعية)، ومتطلبات التوطين والنطاقات إن كانت للنشاط عمالة. وما لم تتيقّن منه قل صراحةً إنه يُراجَع مع مختص","economicImpact":"الأثر الاقتصادي والاجتماعي: فرص العمل المتوقعة في التشغيل وفي التنفيذ، والإنفاق على سلسلة الإمداد المحلية، والعائد على المالية العامة من زكاة وضرائب ورسوم، والتوافق مع التوجه الوطني إن وُجد — بأرقام تقديرية مشتقة من أرقام الدراسة لا بعبارات إنشائية","facilitySizing":"مقاس التمويل المطلوب — لماذا هذا الرقم بالذات لا أكثر ولا أقل. ابنِ الجواب على أعمق نقطة نقدية ورأس المال العامل الفعلي اللازم المحسوبين أعلاه: متى تبلغ ذروة الاحتياج ومتى تبدأ في الانحدار وبأي سبب. ثم احسم: هل المطلوب حدٌّ ائتماني يُسحب على دفعات ويُطفأ من المتحصّلات ثم يُعاد سحبه، أم مبلغٌ مقطوع؟ وإن كان الإنفاق الرأسمالي على مراحل أو كانت المتحصّلات ترد قبل اكتمال المشروع فقل صراحةً إنه حدٌّ لا مبلغ، وبيّن أن تكلفة المشروع قد تفوق الحدّ وأن الفارق يموّله المشروع من دورته — وهذا ما يجعل حدّاً أصغر يكفي مشروعاً أكبر. وفي المقابل: إن كان العميل قد طلب مبلغاً يغطّي استخداماً معيّناً كاملاً — أصلاً وتنفيذاً معاً — فقِس الحدّ على ذلك الاستخدام كاملاً وقل صراحةً إن المشروع يكتمل من التسهيل وحده ولا يحتاج ريالاً من خارجه، ثم بيّن ذروة المسحوب فعلياً مقابل الحدّ، فالفرق بينهما هو هامش الأمان لا مالٌ مهدور. ولا تذكر رقماً غير الأرقام المحسوبة أعلاه","securityStructure":"بنية الضمان وقراءة التعرّض — ما الذي تُتيحه بنية المشروع نفسها من ضمانٍ للمموّل: أصلٌ يُشترى بالتمويل ويُرهن باسم المنشأة، أو متحصّلاتٌ ترد إلى حسابٍ محدد، أو صرفٌ على شهادات إنجاز فيتحوّل التمويل إلى أصلٍ ملموس ريالاً بريال، أو وثيقة تأمين، أو أصولٌ قائمة ذكرها العميل. ثم اقرأ التعرّض بالأرقام المحسوبة: ذروته ومتى تقع وما يقابله من أصل، وكيف ينحدر بعدها. ولا تكتب أن العميل يقدّم ضماناً شخصياً أو كفالةً أو سنداً لأمر أو رهن أصلٍ أو أي تعهّد لم يذكره هو في بياناته. ثم اعرض صيغتي الضمان المتاحتين صراحةً: (أ) رهنٌ على الأصل الذي يُشترى بالتمويل، تُذكر قيمته وكيف تنمو مع الصرف ونسبة تغطيتها للرصيد القائم؛ (ب) أو تأمينٌ ائتمانيٌّ على مبلغ التمويل عبر شركات التأمين المرخّصة، بوليصةٌ لصالح المموّل يتحمّل المشروع قسطها — وهي الصيغة التي تُغني عن المساهمة النقدية حين يتمسّك المموّل بنسبة دينٍ إلى تكلفة. وقل إن للمموّل أن يأخذ إحداهما أو كلتيهما. ولا تكتب أن العميل يقدّم ضماناً شخصياً أو كفالةً أو سنداً لأمر أو رهن أصلٍ أو أي تعهّد لم يذكره هو في بياناته. واختم بسطرٍ صريح: حزمة الضمانات النهائية متروكة لسياسة المموّل ويُتَّفق عليها عند خطاب الشروط، وما ورد وصفٌ لما تُتيحه البنية لا تعهّدٌ من الطالب","remediation":"ما يحتاج معالجة — وكيف عولج. جدول بعمودين: البند | المعالجة القائمة. اذكر بصراحةٍ كاملة كل ما يُضعف الملف في عين لجنة الائتمان — سجلٌّ تشغيليٌّ قصير، تركّزُ عملاء، غيابُ ضمانٍ عيني، نشاطٌ مسجَّل لا يطابق المشروع، تغطيةٌ ضيقة، اعتمادٌ على طرفٍ واحد، موسميةٌ في التدفق — ولا تُسقط بنداً لأنه محرج. لكن **لكل بندٍ معالجته في العمود المقابل**: إجراءٌ قائمٌ فعلاً أو مُدرَجٌ في خطة التنفيذ أو خاصيّةٌ في الهيكل تُبطل أثره. ثلاثة إلى ستة بنود. ⚠️ ولا تكتب بنداً بلا معالجة: البند بلا معالجة سببُ رفضٍ كتبناه بأيدينا، والبند بمعالجته دليلُ أن المكتب فكّر قبل أن يُسأل","completionPath":"مسار استكمال الملف: المستندات والخطوات الناقصة مرتّبةً بمراحلها لا بصيغة نقص. جدول بثلاثة أعمدة: البند | موضعه في المسار (المرحلة الأولى/الثانية/الثالثة أو «حزمة المنشأة — تُرفق عند التقديم») | المدة التقديرية. وابدأ بسطرٍ يقول إن الترتيب تسلسلٌ نظاميٌّ لا نقصٌ في الجاهزية. واذكر التراخيص والعقود والمستندات التي ذكرتها في قسم الجدوى القانونية، ولا تخترع مستنداً لا يلزم هذا النشاط","marketBenchmark":"مُدخلات الدراسة مقارنةً بالسوق ومقاس المشروع — جدول بأربعة أعمدة: البند | قيمة المشروع | نطاق السوق | الحكم. قارن أهمّ ثلاثة إلى خمسة مُدخلات (سعر البيع للوحدة، تكلفة الوحدة أو المتر، مدّة التنفيذ، سعر الأصل إن وُجد، ونسبة الأصل من الإيراد إن كانت ذات دلالة) بنطاقٍ سوقيٍّ منشورٍ أو عرفِ قطاع، واحكم على كلٍّ منها: داخل النطاق أم عند طرفه أم خارجه. ثم صفٌّ أخير للمقاس نفسه: المساحة أو الطاقة أو عدد الوحدات مقابل النطاق المعتاد لمشروعٍ من هذا النوع. واختم بفقرةٍ تشرح لماذا هذا هو النطاق: ماذا يحدث دونه (تكاليف ثابتة لا تتوزّع) وماذا يحدث فوقه (طاقةٌ تفوق امتصاص السوق فتطول الدورة وتثقل كلفة التمويل)","exitRoutes":"مسارا التصريف وشكل السداد. أولاً: إن كان للمشروع أكثر من مسارٍ للبيع أو التصريف أو التشغيل، اعرضهما في جدولٍ بأعمدة: المسار | أثره على ذروة الاحتياج النقدي | أثره على التدفق | الحكم — مستنداً إلى الأرقام المحسوبة أعلاه وحدها، ثم أوصِ بأحدهما وقل بكم يفوق الآخر. وإن كان المسار واحداً لا غير فقل ذلك واذكر ما الذي يجعله واحداً. ثانياً: شكلُ السداد — اربط فترة السماح بمدّة التأسيس أو التنفيذ قبل أول إيراد (سماحٌ يساوي تلك المدّة ومبرَّرٌ بها لا بالطلب)، ثم قل على كم شهراً تُجدوَل الأقساط بعدها، وهل يجوز الإطفاء المبكّر من المتحصّلات بلا غرامة. ولا تذكر مدّةً بلا تبريرٍ من الجدول الزمني نفسه","assumptionsNote":"جدول الافتراضات بثلاثة أعمدة: المُدخل | القيمة | المصدر ومبرّر الاعتماد. ⚠️ ولا تكتب «إفادة الطالب» مصدراً وحيداً لسعر بيعٍ أو تكلفةٍ أو مدّة تنفيذٍ متى وُجد لها متوسطٌ سوقي — اكتب متوسط السوق وانسبه إليه، وقل هل طابقته إفادةُ العميل أم خالفتها وبكم. وما لا مرجع سوقياً له يُكتب «افتراض المكتب». واختم بسطرٍ يقول إن المُدخلات السعرية مسحوبةٌ من السوق لا من إفادة الطالب، لأن الوثيقة تُقرأ من لجنة ائتمان","risks":"مخاطر هذا المشروع تحديداً بصيغة جدول بأربعة أعمدة: المخاطرة | الاحتمال (مرتفع/متوسط/منخفض) | الأثر (مرتفع/متوسط/منخفض) | إجراء التخفيف الذي ينفّذه — بلا إحصاءات تعثّر عامة للقطاع","conclusion":"الخلاصة والتوصية بصراحة، وتُفصَل فيها الجدوى الاقتصادية (هل يستحق المشروع رأس المال) عن الجدوى الائتمانية (هل يقدر على السداد) — فقد يكون الجواب مختلفاً فيهما","funderQA":"ثمانية أسئلة تطرحها لجنة الائتمان على هذا الملف تحديداً وإجابة كل سؤال من أرقام الدراسة — بصيغة جدول بعمودين: السؤال | الإجابة. ابدأ بأصعبها: ضيق التغطية، وسقوط السيناريو المتحفظ، وغياب السجل التشغيلي، وارتفاع سعر الوحدة عن السوق، والضمان. لا تُجمّل، وأجب برقم لا بعبارة عامة"}';

  // استخراج JSON من نص قد يحوي مقدمة أو عدة كتل — نجرب من آخر '{' للخلف
  const pick = (raw: string, need = 'executiveSummary'): Record<string, unknown> | null => {
    const c = raw.replace(/```json|```/g, '').trim();
    const starts: number[] = [];
    for (let k = 0; k < c.length; k++) if (c[k] === '{') starts.push(k);
    // نجرب كل بداية مع كل نهاية محتملة، من الأطول للأقصر
    const ends: number[] = [];
    for (let k = c.length - 1; k >= 0; k--) if (c[k] === '}') ends.push(k);
    for (const st of starts) {
      for (const en of ends) {
        if (en <= st) break;
        try {
          const o = JSON.parse(c.slice(st, en + 1));
          if (o && typeof o === 'object' && o[need]) return o as Record<string, unknown>;
        } catch { /* جرّب نهاية أقصر */ }
      }
    }
    // رد مقطوع: نلتقط الحقول النصية المكتملة يدوياً حتى لا تضيع الأقسام
    const keys = ['topNumbers', 'executiveSummary', 'marketStudy', 'competition', 'swot', 'targetSegments', 'operationalPlan', 'legalCompliance', 'economicImpact', 'technicalStudy', 'facilitySizing', 'securityStructure', 'marketBenchmark', 'exitRoutes', 'remediation', 'completionPath', 'assumptionsNote', 'risks', 'conclusion', 'funderQA', 'facts'];
    const out: Record<string, unknown> = {};
    for (const k of keys) {
      const m = c.match(new RegExp('"' + k + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"'));
      if (m) out[k] = m[1].replace(/\\n/g, '\n').replace(/\\"/g, '"');
    }
    return out[need] ? out : null;
  };

  let diag = '';
  const call = async (body: Record<string, unknown>, ms: number, tag: string): Promise<string | null> => {
    const ac = new AbortController();
    const to = setTimeout(() => ac.abort(), ms);
    try {
      const r = await fetch(ANTHROPIC_URL, {
        method: 'POST', signal: ac.signal,
        headers: { 'Content-Type': 'application/json', 'x-api-key': process.env.ANTHROPIC_API_KEY as string, 'anthropic-version': '2023-06-01' },
        body: JSON.stringify({ model: MODEL, ...body }),
      });
      clearTimeout(to);
      if (!r.ok) { diag += tag + 'HTTP ' + r.status + ' — ' + (await r.text()).slice(0, 200); return null; }
      const d = await r.json();
      return (d.content || []).filter((c: { type: string }) => c.type === 'text').map((c: { text: string }) => c.text).join('\n');
    } catch (e) {
      clearTimeout(to);
      diag += tag + 'استثناء — ' + (e instanceof Error ? e.name + ': ' + e.message : String(e)).slice(0, 200);
      return null;
    }
  };

  // ═══ النداء الأول: بحث سوق فقط، مخرجاته قصيرة فيبقى سريعاً ═══
  const researchPrompt = 'ابحث في الويب عن مؤشرات السوق السعودي لهذا النشاط: ' + ctx.sectorText
    + (ctx.city ? ' في ' + ctx.city : '') + '. وصف المشروع: ' + ctx.projectDescription + '\n'
    + 'حجم المشروع: ' + scaleLabel + '، ونطاقه التنافسي هو ' + scaleRadius + '.\n'
    + 'اجمع تحديداً: حجم السوق ونموه المتوقع · متوسط إنفاق العميل أو متوسط قيمة الطلب · مستوى الأسعار وبنية المنافسة عند حجم المشروع ونطاقه تحديداً (لا على مستوى السلاسل الوطنية إن كان المشروع صغيراً) · أحدث الاشتراطات التنظيمية المؤثرة · مؤشرات التكلفة المحلية كالإيجار وأجور التشغيل في المدينة.\n'
    + 'لا تجمع معدلات تعثّر أو إغلاق عامة للقطاع — لا تُستخدم في الدراسة.\n'
    + 'جودة المصدر: إذا وجدت الرقم في صحيفة أو مدونة تنقل عن تقرير، فاذهب إلى التقرير نفسه واذكره باسمه؛ وإن تعذّر فلا تجمع ذلك الرقم أصلاً. ولا تعتمد مدونة شركة تنقل إحصاءً حكومياً — اذكر الجهة الحكومية أو اتركه.\n'
    + 'وإذا تعارضت مصادر في رقم واحد فاذكر التقديرين معاً مع اسم كل مصدر، لا تخفِ التعارض.\n'
    + 'أرجع JSON فقط بلا أي نص آخر: {"facts":"نقاط مرقّمة، كل نقطة رقم واحد مع اسم مصدره وسنته","sources":["اسم الجهة — الرابط الكامل — السنة"]}\n'
    + 'في sources: اسم الجهة الحقيقي لا اسم النطاق، والرابط كاملاً يبدأ بـ https، وبلا تكرار.\n'
    + 'لا تكتب رقماً لم تره في نتيجة بحث فعلية، ولا تنسب رقماً لمصدر لم تفتحه.';
  const t0 = Date.now();

  // القسم «ب» لا يحتاج نتائج البحث، فيُطلق فوراً ويعمل بالتوازي مع البحث — هذا ما يقصّ زمن الانتظار فعلاً
  // ★ ٩٠٠٠ لا ٧٠٠٠: أُضيف قسمان إلى «ب» (مقاس التمويل وبنية الضمان)، ورَدٌّ
  //   مقطوع هنا يُسقط الخلاصة وأسئلة الممول لأنهما في آخر الـJSON.
  const pB = call({
    max_tokens: 13500,
    messages: [{ role: 'user', content: mkPrompt('أقسام السوق والمنافسة تُكتب في مهمة منفصلة — لا تكتبها هنا.\n\n', SPEC_B) }],
  }, 215000, ' | الأقسام الفنية: ');

  const rTxt = await call({
    max_tokens: 2500,
    tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 5 }],
    messages: [{ role: 'user', content: researchPrompt }],
  }, 85000, ' | بحث السوق: ');
  const rJson = rTxt ? pick(rTxt, 'facts') as { facts?: string; sources?: string[] } | null : null;
  const facts = rJson && typeof rJson.facts === 'string' ? rJson.facts.trim() : '';
  const foundSources = rJson && Array.isArray(rJson.sources) ? rJson.sources.filter(x => typeof x === 'string') : [];
  const marketBlock = facts
    ? 'نتائج بحث السوق (من بحث فعلي — استند إليها وانسب كل رقم لمصدره):\n' + facts + '\n\nالمصادر المتاحة: ' + foundSources.join(' | ') + '\n\n'
    : 'لم تصل نتائج بحث سوق لهذه التشغيلة — اكتب أرقام السوق من معرفتك بالسوق السعودي بصفتها تقديرات استرشادية مبنية على مؤشرات القطاع تُحدَّث بمصادر منشورة قبل الاعتماد النهائي، واترك sources فارغة.\n\n';

  // ═══ القسم «أ»: يبدأ فور وصول البحث، ويُنتظر مع «ب» معاً ═══
  const pA = call({
    max_tokens: 9500,
    messages: [{ role: 'user', content: mkPrompt(marketBlock, SPEC_A) }],
  }, Math.max(60000, 235000 - (Date.now() - t0)), ' | أقسام السوق: ');

  const [aTxt, bTxt] = await Promise.all([pA, pB]);
  const a = aTxt ? pick(aTxt, 'executiveSummary') : null;
  const b = bTxt ? pick(bTxt, 'technicalStudy') : null;
  if (aTxt && !a) diag += ' | أقسام السوق: وصل رد بطول ' + aTxt.length + ' حرفاً بلا JSON صالح — بدايته: ' + aTxt.slice(0, 100);
  if (bTxt && !b) diag += ' | الأقسام الفنية: وصل رد بطول ' + bTxt.length + ' حرفاً بلا JSON صالح — بدايته: ' + bTxt.slice(0, 100);
  if (!a && !b) return { sections: empty(), result, credit, error: 'تعذّر توليد الأقسام النصية' + diag };

  // من «ب» نأخذ حقوله الأربعة فقط — حتى لا يطمس حقل sources القادم من «أ»
  const bOnly: Record<string, unknown> = {};
  for (const k of ['technicalStudy', 'operationalPlan', 'legalCompliance', 'economicImpact', 'facilitySizing', 'securityStructure', 'marketBenchmark', 'exitRoutes', 'remediation', 'completionPath', 'assumptionsNote', 'risks', 'conclusion', 'funderQA']) if (b && b[k]) bOnly[k] = b[k];
  const sections = { ...empty(), ...(a || {}), ...bOnly } as FeasibilitySections;
  // قائمة المصادر تُؤخذ من البحث الفعلي لا من كتابة النموذج — هو يعيد صياغتها فتتكرر وتفقد روابطها
  if (foundSources.length) sections.sources = foundSources;
  const missing = !a ? 'أقسام السوق والمنافسة لم تصل' : !b ? 'الأقسام الفنية والمخاطر والخلاصة لم تصل' : '';
  const warn = missing || (facts ? '' : 'أرقام السوق تقديرات استرشادية — لم تصل نتائج البحث في هذه التشغيلة');
  return { sections, result, credit, error: warn ? warn + diag : undefined };
}

function empty(): FeasibilitySections {
  return { topNumbers: '', executiveSummary: '', marketStudy: '', competition: '', swot: '', operationalPlan: '', legalCompliance: '', economicImpact: '', technicalStudy: '', facilitySizing: '', securityStructure: '', marketBenchmark: '', targetSegments: '', exitRoutes: '', remediation: '', completionPath: '', assumptionsNote: '', risks: '', conclusion: '', funderQA: '', sources: [] };
}

// النموذج يكتب markdown أحياناً رغم المنع — نحوّله بدل أن يظهر خاماً في وثيقة تُسلَّم لبنك
function mdToHtml(body: string, title: string): string {
  // داخل الخلايا: تشديد فقط — لا نحذف '#' لأنه قد يكون عنوان عمود «رقم»
  const cell = (t: string) => t
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/__(.+?)__/g, '<strong>$1</strong>');
  const inline = (t: string) => cell(t)
    .replace(/^\s*#{1,6}\s+/, '')
    .replace(/^\s*[-*]\s+/, '• ');
  const bare = (t: string) => t.replace(/[*_#:：\s]/g, '');
  const parts: string[] = [];
  let text: string[] = [];
  let tbl: string[][] = [];
  const flushText = () => { if (text.length) { parts.push(text.join('<br>')); text = []; } };
  const flushTable = () => {
    if (!tbl.length) return;
    const rows = tbl.filter(r => !r.every(c => /^:?-{2,}:?$/.test(c)));
    if (rows.length) {
      const head = rows[0], rest = rows.slice(1);
      parts.push('<table class="fz"><thead><tr><th>' + head.map(cell).join('</th><th>') + '</th></tr></thead><tbody>'
        + rest.map(r => '<tr><td>' + r.map(cell).join('</td><td>') + '</td></tr>').join('') + '</tbody></table>');
    }
    tbl = [];
  };
  let first = true;
  for (const ln of String(body).split('\n')) {
    if (/^\s*\|.*\|\s*$/.test(ln)) {
      flushText();
      tbl.push(ln.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(c => c.trim()));
      continue;
    }
    flushTable();
    if (first && ln.trim()) { first = false; if (bare(ln) === bare(title)) continue; }
    text.push(inline(ln));
  }
  flushTable(); flushText();
  return parts.join('');
}

// صفحة القرار: ما يقرؤه محلل الائتمان في دقيقة قبل أن يقرر إكمال الملف من عدمه
function decisionPage(ctx: FeasibilityContext, r: FeasibilityResult, credit?: CreditPack, bp?: ReturnType<typeof computeBreakPoints>): string {
  const m = (v: number) => Math.round(v).toLocaleString('en-US');
  const eq = r.totalInvestment > 0 ? (ctx.inputs.ownFunds / r.totalInvestment) * 100 : 0;
  const row = (k: string, v: string) => '<tr><th>' + k + '</th><td>' + v + '</td></tr>';
  return '<div class="dp"><div class="dph">ملخص للجهة الممولة — صفحة القرار</div><table class="fz">'
    + row('الطلب', m(ctx.inputs.financingAmount) + ' ريال على ' + ctx.inputs.financingYears + ' سنوات بكلفة سنوية ' + ctx.inputs.financingRate + '%')
    + row('الغرض', ctx.projectKind === 'new' ? 'تأسيس مشروع جديد — ' + ctx.sectorText : 'توسعة نشاط قائم — ' + ctx.sectorText)
    + row('استخدامات التمويل', 'تكلفة رأسمالية ' + m(ctx.inputs.capex) + ' ريال + رأس مال عامل ' + m(ctx.inputs.workingCapital) + ' ريال = ' + m(r.totalInvestment) + ' ريال')
    + row('مساهمة المؤسس', m(ctx.inputs.ownFunds) + ' ريال (' + eq.toFixed(0) + '% من إجمالي الاستثمار) — فجوة التمويل ' + m(r.fundingGap) + ' ريال')
    + row('القسط السنوي', m(r.annualInstalment) + ' ريال')
    + (credit && credit.minDscr !== null ? row('تغطية خدمة الدين', 'أدناها ' + credit.minDscr.toFixed(2) + '× ومتوسطها ' + (credit.avgDscr as number).toFixed(2) + '× — ' + credit.verdict) : '')
    + (credit && credit.combined && credit.combined.minDscr !== null ? row('التغطية المجمّعة للمنشأة بعد التوسعة', 'أدناها ' + credit.combined.minDscr.toFixed(2) + '× ومتوسطها ' + (credit.combined.avgDscr as number).toFixed(2) + '× — ' + credit.combined.verdict) : '')
    + (bp && bp.headroomPct !== null ? row(bp.headroomPct >= 0 ? 'هامش التراجع المحتمل في المبيعات' : 'الزيادة المطلوبة في المبيعات لبلوغ 1.25×', Math.abs(bp.headroomPct).toFixed(1) + '%') : '')
    + (credit && credit.deepestMonth ? row('أعمق نقطة نقدية في السنة الأولى', 'الشهر ' + credit.deepestMonth.month + ' عند ' + m(credit.deepestMonth.cumulative) + ' ريال — رأس مال عامل فعلي لا يقل عن ' + m(credit.workingCapitalNeeded) + ' ريال') : '')
    + (credit && credit.scenarios[0] ? row('السيناريو المتحفظ (−20% مبيعات، +10% تكاليف)', (credit.scenarios[0].dscrY1 === null ? '—' : credit.scenarios[0].dscrY1.toFixed(2) + '×') + ' — ' + credit.scenarios[0].verdict) : '')
    + row('نقطة التعادل السنوية', m(r.breakEvenRevenue) + ' ريال — أي ' + (r.years[0].revenue > 0 ? ((r.breakEvenRevenue / r.years[0].revenue) * 100).toFixed(0) + '% من إيراد السنة الأولى المخطط' : '—'))
    + row('فترة استرداد مساهمة المؤسس', r.paybackYears === null ? 'لا تُسترد خلال خمس سنوات بهذه الافتراضات' : r.paybackYears.toFixed(1) + ' سنة')
    + '</table><div class="note">هذه الصفحة خلاصة محسوبة من الجداول التالية، وليست بديلاً عنها. الدراسة كاملةً تسند كل رقم فيها.</div></div>';
}

// الجهات المرشحة — تُقرأ من نتائج المطابقة المحفوظة للعميل، ولا يولّدها نموذج
function funderTable(funders?: FunderRow[]): string {
  if (funders && funders.length) funders = orderForClient(funders as never) as never;
  if (!funders || !funders.length) {
    return '<h2>الجهات التمويلية المرشحة</h2><div class="note">لم تُشغَّل مطابقة الجهات لهذا العميل بعد. تُشغَّل من لوحة التقديم، وعندها تظهر هنا الجهات التي تنطبق شروطها على هذا الملف ومتطلبات كل واحدة منها.</div>';
  }
  const esc = (v: unknown) => v === null || v === undefined || v === '' ? '—' : String(v);
  // وسم عائلة المنتج، وتنبيه مكتوب على كل إجارة بأن الأصل يبقى مرهوناً —
  // فيقرأ العميل الفرق بين «يملك» و«يستأجر» قبل أن يسأل عنه
  const rows = funders.map(x => {
    const fam = familyOf(x as never);
    const pledge = pledgeWarning(x as never);
    return '<tr><td>' + [
    '<b>' + esc(x.provider) + '</b>'
      + '<br><span style="font-size:10.5px;color:' + (pledge ? '#9A5B25' : '#1E7A5A') + ';font-weight:bold">' + FAMILY_LABEL[fam] + '</span>'
      + (x.product ? '<br><span style="font-size:11px;color:#666">' + x.product + '</span>' : '')
      + (pledge ? '<br><span style="font-size:10.5px;color:#9A5B25">⚠︎ ' + pledge + '</span>' : ''),
    esc(x.region),
    esc(x.amount_range),
    esc(x.requirements).slice(0, 190)
      + (x.required_docs ? '<br><span style="font-size:11px;color:#666"><b>المستندات:</b> ' + String(x.required_docs).slice(0, 190) + '</span>' : ''),
    (x.gaps && x.gaps.length ? x.gaps.slice(0, 3).join(' · ') : '—'),
    esc(x.apply_channel),
    ].join('</td><td>') + '</td></tr>';
  }).join('');
  return '<h2>الجهات التمويلية المرشحة لهذا الملف</h2>'
    + '<table class="fz sm"><thead><tr><th>الجهة</th><th>النطاق</th><th>حدود المبلغ</th><th>المتطلبات والمستندات</th><th>الفجوات قبل التقديم</th><th>طريقة التقديم</th></tr></thead><tbody>'
    + rows + '</tbody></table>'
    + '<div class="note">الترتيب يقدّم ما يمنحك سيولة أو ملكية على ما يبقي الأصل مرهوناً، ثم بحسب مطابقة شروط كل جهة لبيانات هذا الملف. عمود «الفجوات» هو ما يلزم استكماله قبل التقديم لتلك الجهة تحديداً، وهو خارطة العمل التنفيذية للمرحلة التالية. ولا تُعد هذه القائمة وعداً بموافقة — القرار للجهة وحدها بعد دراستها للملف. وتُذكر هنا قناة التقديم والمستندات المطلوبة؛ أما روابط التقديم المباشرة ونصوص المخاطبة والمتابعة حتى الرد فتُنفَّذ ضمن خدمة مخاطبة الجهات.</div>';
}

export function buildFeasibilityHTML(ctx: FeasibilityContext, s: FeasibilitySections, r: FeasibilityResult, warn?: string, credit?: CreditPack, funders?: FunderRow[]): string {
  const sec = (title: string, body: string) => body ? '<h2>' + title + '</h2><div class="bd">' + mdToHtml(body, title) + '</div>' : '';
  const srcList = (s.sources || []).length ? '<h2>المصادر</h2><ul>' + s.sources.map(x => '<li>' + x + '</li>').join('') + '</ul>' : '';
  const bp = credit ? computeBreakPoints(ctx.inputs, r, credit) : undefined;
  // ═══ الاسم ═══
  // «الاقتصادية» عنوانٌ مخزَّن في قاعدة البيانات لا يُمسّ، لكنه ليس اسم
  // المنتج. والاسم المعروض هو «الجدوى الائتمانية» — وبه يفترق منتج المكتب
  // عن دراسة السوق: هذه مكتوبة بلغة محلل الائتمان. وكان العنوان مكتوباً هنا
  // بيده فبقي «الاقتصادية» على الوثيقة نفسها بينما تغيّر في كل مكان سواها.
  const docTitle = ctx.quick ? 'الفحص الائتماني للمشروع' : 'دراسة الجدوى الاقتصادية والائتمانية';

  // ═══ الهوية ═══
  // كانت الوثيقة بخط Arial وذهبٍ #B8860B — لا يشبهان المنصة ولا وثيقة الحكم
  // الائتماني الخارجة من المكتب نفسه. وهي أغلى ما يُسلَّم، ويحملها العميل إلى
  // بنك: فاختلاف هويتها عن هوية مُرضي يجعلها تُقرأ كملفٍّ عابر لا كمخرَج مكتب
  // مرخَّص. فصارت بلون المنصة وخطّها: أخضر #1A3D34 وذهبي #C9A84C وخط القاهرة.
  return '<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width,initial-scale=1">'
    + '<title>' + docTitle + ' — ' + ctx.companyName + '</title>'
    + '<style>'
    + "@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;700;900&family=Amiri:wght@700&display=swap');"
    + '*{box-sizing:border-box}'
    + 'body{font-family:Cairo,system-ui,sans-serif;color:#12302A;background:#F4F7F6;line-height:1.95;margin:0;padding:22px 14px 50px}'
    + '.pg{max-width:900px;margin:0 auto;background:#fff;border:1px solid #E1EDE8;border-radius:16px;padding:0 0 30px;overflow:hidden}'
    + '.hd{background:#1A3D34;color:#fff;padding:30px 30px 26px}'
    + '.hd .eb{font-size:11px;letter-spacing:.14em;color:#C9A84C;font-weight:900;margin-bottom:10px}'
    + '.hd h1{font-family:Amiri,serif;font-size:29px;line-height:1.5;margin:0 0 8px;color:#fff}'
    + '.hd .co{font-size:15px;font-weight:900;color:#E4CE93}'
    + '.hd .meta{font-size:12.5px;color:#BFD4CD;font-weight:400;margin-top:3px}'
    + '.bx{padding:0 30px}'
    + 'h2{font-size:18.5px;color:#1A3D34;margin:32px 0 10px;padding-bottom:8px;border-bottom:2px solid #EDF4F1;position:relative}'
    + 'h2::after{content:"";position:absolute;right:0;bottom:-2px;width:52px;height:2px;background:#C9A84C}'
    + 'p{font-size:14px;margin:0 0 12px}'
    + '.bd{font-size:14px}'
    + '.bd b,.bd strong{color:#1A3D34}'
    + 'table.fz{width:100%;border-collapse:collapse;margin:14px 0;font-size:13px}'
    + 'table.fz th{background:#1A3D34;color:#fff;text-align:right;padding:9px 11px;font-weight:900;font-size:12.5px}'
    + 'table.fz td{padding:9px 11px;border-bottom:1px solid #EFF5F2;text-align:right;vertical-align:top}'
    + 'table.fz tr:nth-child(even) td{background:#FAFCFB}'
    + 'table.fz.sm{font-size:11.5px}table.fz.sm th,table.fz.sm td{padding:6px 8px}'
    + '.note{background:#FBF7EC;border-right:4px solid #C9A84C;padding:13px 16px;margin:16px 0;font-size:13px;line-height:2}'
    + '.dp{border:2px solid #C9A84C;background:#FCFAF4;border-radius:14px;padding:18px 20px;margin:20px 0}'
    + '.dph{font-family:Amiri,serif;color:#1A3D34;font-weight:700;font-size:19px;margin-bottom:8px}'
    + '.dp table.fz th{width:38%;background:#22493F}'
    + 'ul{padding-inline-start:0;list-style:none;margin:0 0 14px}'
    + 'li{font-size:13.5px;line-height:1.95;margin-bottom:6px;padding-inline-start:16px;position:relative}'
    + 'li::before{content:"";position:absolute;right:0;top:10px;width:5px;height:5px;background:#C9A84C}'
    + '.ft{text-align:center;font-size:11.5px;color:#9DB3AB;padding:18px 30px 0;margin-top:26px;border-top:1px solid #EFF5F2}'
    // المتصفّح يُسقط كل لون خلفية عند الطباعة إلا بهذا الأمر — فكانت الوثيقة
    // تخرج PDF بيضاء بلا رأسٍ أخضر ولا رؤوس جداول، أي بلا هوية. وهي تُطبع
    // أكثر مما تُقرأ على الشاشة: العميل يحملها إلى بنك.
    + '*{-webkit-print-color-adjust:exact;print-color-adjust:exact}'
    + '@media print{body{background:#fff;padding:0}.pg{border:none;border-radius:0}'
    + 'h2,.dp,table.fz,.note{break-inside:avoid}}'
    + '</style></head><body><div class="pg">'
    + '<div class="hd"><div class="eb">مُرضي · حلول المرضي للاستشارات المالية · ترخيص FL-457927015</div>'
    + '<h1>' + docTitle + '</h1>'
    + '<div class="co">' + ctx.companyName + '</div>'
    + '<div class="meta">' + [ctx.crNumber ? 'سجل تجاري ' + ctx.crNumber : '', ctx.city || ''].filter(Boolean).join(' · ') + '</div></div>'
    + '<div class="bx">'
    + '<p>' + ctx.projectDescription + '</p>'
    // نطاقُ الدراسة يُكتب في صدرها لا في هامشها: ما لا تقوم مقامه يُقال
    // ابتداءً، فلا يُقاس عليها ما لم تُعدّ له، ولا يُحمَّل المكتبُ رأياً
    // لم يُبدِه. وهي تُقرأ أمام لجنةٍ تعرف الفرق بين دراسةِ حجمٍ وتفاوض
    // وبين تقييمٍ عقاريٍّ معتمد أو دراسةٍ فنيةٍ لمكتبٍ هندسي.
    + '<div class="note"><b>نطاق الدراسة وحدودها.</b> أُعِدَّت على مُدخلاتٍ قدّمها الطالب وافتراضاتٍ مبيَّنةٍ في جدول الافتراضات، ولم تُدقَّق تلك المُدخلات من طرفٍ مستقل. '
      + 'وهي أداةُ تحديد حجمٍ وهيكلٍ وتفاوض، ولا تقوم مقام: التقييم المعتمد للأصول، ولا الدراسة الفنية التفصيلية للمكتب الهندسي، ولا الاستشارة الضريبية أو القانونية المتخصّصة، ولا تدقيق القوائم المالية. '
      + 'وتُحدَّث كلّما تغيّر مُدخلٌ جوهري.</div>'
    + decisionPage(ctx, r, credit, bp)
    + (s.topNumbers ? '<div class="dp"><div class="dph">أربعة أرقام تُغني عن قراءة الوثيقة</div>' + mdToHtml(s.topNumbers, '') + '</div>' : '')
    + sec('الملخص التنفيذي', s.executiveSummary)
    + '<h2>المؤشرات المالية</h2>' + renderFeasibilitySummary(r)
    + '<h2>قائمة الدخل المتوقعة لخمس سنوات</h2>' + renderProjectionTable(r)
    + '<h2>التدفق النقدي المتوقع لخمس سنوات</h2>' + renderCashflowTable(r)
    + '<div class="note">الأرقام أعلاه محسوبة من افتراضات العميل المذكورة في جدول الافتراضات، وليست وعداً بعائد. وأي تغيّر في السعر أو حجم المبيعات أو التكاليف يغيّر النتائج.</div>'
    + (credit ? '<h2>ملف الائتمان — تغطية خدمة الدين</h2>' + renderCreditTable(credit) + (credit.combined ? '<h2>التغطية المجمّعة — المنشأة كلها بعد التوسعة</h2>' + renderCombinedTable(credit.combined) : '') + '<h2>التدفق النقدي الشهري للسنة الأولى</h2>' + renderMonthlyTable(credit) + '<h2>تحليل الحساسية — ثلاثة سيناريوهات</h2>' + renderScenarioTable(credit) : '')
    + (bp ? '<h2>حدود الأمان — ما الذي يجب أن يكون صحيحاً</h2>' + renderBreakPointsTable(bp, r) : '')
    + (ctx.quick ? '' :
        sec('دراسة السوق', s.marketStudy)
      + sec('الشرائح المستهدفة', s.targetSegments)
      + sec('المنافسون', s.competition)
      + sec('الموقع التنافسي — القوة والفرص والتهديدات', s.swot)
      + sec('ما يحتاج معالجة — وكيف عولج', s.remediation)
      + sec('الدراسة الفنية', s.technicalStudy)
      + sec('الجدوى التشغيلية وخطة التسويق', s.operationalPlan)
      + sec('الجدوى القانونية والنظامية', s.legalCompliance)
      + sec('مقاسُ التمويل المطلوب — لماذا هذا الرقم', s.facilitySizing)
      + sec('مسارا التصريف وشكل السداد', s.exitRoutes)
      + sec('بنية الضمان وقراءة التعرّض', s.securityStructure)
      + sec('مسار استكمال الملف', s.completionPath)
      + sec('مُدخلات الدراسة مقارنةً بالسوق ومقاس المشروع', s.marketBenchmark)
      + sec('جدول الافتراضات', s.assumptionsNote)
      + sec('المخاطر وإجراءات التخفيف', s.risks)
      + sec('الأثر الاقتصادي والاجتماعي', s.economicImpact)
      + sec('الخلاصة والتوصية', s.conclusion)
      + funderTable(funders)
      + sec('أسئلة الجهة الممولة المتوقعة وإجاباتها', s.funderQA)
      + srcList)
    + (ctx.quick ? '<div class="note"><b>ما يشمله هذا الفحص وما لا يشمله:</b> الأرقام أعلاه محسوبة بالكامل من مدخلاتك، وتُظهر قدرة المشروع على خدمة الدين وحدوده الآمنة ونقطة تعادله وأعمق نقطة سيولة فيه. '
      + 'ولا يشمل هذا الفحص دراسة السوق بمصادرها، ولا تحليل المنافسة في نطاق المشروع، ولا الدراسة الفنية والمخاطر، ولا قائمة الجهات التمويلية المرشّحة بفجواتها ومتطلباتها وطرق التقديم إليها — وهذه كلها في دراسة الجدوى الكاملة. '
      + 'وقيمة هذا الفحص تُخصم بالكامل من الدراسة الكاملة عند إكمالها.</div>' : '')
    + '</div>'
    + '<div class="ft"><b style="color:#1A3D34;font-size:13px">د. عبدالحكيم المرضي</b><br>'
    + 'مستشار مالي معتمد · ترخيص FL-457927015 · حلول المرضي للاستشارات المالية · سجل تجاري 7039663724<br>'
    + 'وثيقة سرّية أُعدّت لصالح ' + ctx.companyName + ' — لا تُتداول خارج أطرافها<br><br>'
    // السطر الأخير ليس تزيّناً: بغيره تُقرأ الوثيقة تعهّداً، فيُفاوَض العميل
    // على ما لم يلتزم به، ويُحمَّل المكتبُ وعداً بتمويلٍ لا يملكه أحد.
    + '<span style="display:block;text-align:right;line-height:1.9;color:#9DB3AB">'
      + '<b>إخلاء مسؤولية.</b> النتائج تقديريةٌ بطبيعتها وتتغيّر بتغيّر الأسعار والتكاليف وظروف السوق. '
      + 'ولا تتضمّن هذه الوثيقة توصيةً بالاستثمار ولا تعهّداً بالحصول على تمويل، ولا تُلزم أيّ جهةٍ تمويليةٍ بقبولٍ أو رفض. '
      + '<b>ولا تُنشئ التزاماً على الطالب تجاه أيّ جهة: وما ورد في «بنية الضمان» وصفٌ لما تُتيحه بنية المشروع لا تعهّدٌ بتقديمه، وتُبحث حزمة الضمانات عند خطاب الشروط.</b> '
      + 'ومسؤولية التحقّق من الأنظمة السارية وقت التنفيذ تقع على الطالب.</span></div>'
    + '</div></body></html>';
}
